import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.5akMI7mQ.js";const g=JSON.parse('{"title":"Commands & Flags Reference","description":"","frontmatter":{},"headers":[],"relativePath":"cli-reference/commands-flags.md","filePath":"cli-reference/commands-flags.md","lastUpdated":1792429063000}'),n={name:"cli-reference/commands-flags.md"};function l(d,t,o,r,c,h){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="commands-flags-reference" tabindex="-1">Commands &amp; Flags Reference <a class="header-anchor" href="#commands-flags-reference" aria-label="Permalink to &quot;Commands &amp; Flags Reference&quot;">​</a></h1><p>Detailed reference for all <code>wednesd</code> commands, arguments, and CLI options.</p><hr><h2 id="global-options" tabindex="-1">Global Options <a class="header-anchor" href="#global-options" aria-label="Permalink to &quot;Global Options&quot;">​</a></h2><p>These options can be passed to <code>wednesd</code> at the top level or used in standalone mode.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:center;">Short</th><th style="text-align:center;">Type</th><th style="text-align:center;">Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--listen</code></td><td style="text-align:center;"><code>-l</code></td><td style="text-align:center;">string</td><td style="text-align:center;"><code>127.0.0.1:8080</code></td><td style="text-align:left;">Host address and port to bind TCP and UDP gateway listeners.</td></tr><tr><td style="text-align:left;"><code>--wasm</code></td><td style="text-align:center;"><code>-w</code></td><td style="text-align:center;">path</td><td style="text-align:center;"><code>None</code></td><td style="text-align:left;">Path to a WebAssembly <code>.wasm</code> component file (used in standalone mode).</td></tr><tr><td style="text-align:left;"><code>--id</code></td><td style="text-align:center;"><code>-i</code></td><td style="text-align:center;">string</td><td style="text-align:center;"><code>hello</code></td><td style="text-align:left;">Ingress route identifier for standalone mode (mounted at <code>/fn/:id</code>).</td></tr><tr><td style="text-align:left;"><code>--global-concurrency</code></td><td style="text-align:center;"></td><td style="text-align:center;">integer</td><td style="text-align:center;"><code>100</code></td><td style="text-align:left;">Maximum number of simultaneous active executions allowed across the entire daemon.</td></tr><tr><td style="text-align:left;"><code>--memory-budget-mb</code></td><td style="text-align:center;"></td><td style="text-align:center;">integer</td><td style="text-align:center;"><code>1200</code></td><td style="text-align:left;">Global memory ceiling in megabytes for the daemon process.</td></tr><tr><td style="text-align:left;"><code>--default-concurrency</code></td><td style="text-align:center;"></td><td style="text-align:center;">integer</td><td style="text-align:center;"><code>16</code></td><td style="text-align:left;">Default concurrency limit for functions that do not specify <code>max_concurrency</code>.</td></tr><tr><td style="text-align:left;"><code>--log-json</code></td><td style="text-align:center;"></td><td style="text-align:center;">boolean</td><td style="text-align:center;"><code>false</code></td><td style="text-align:left;">Emits structured JSON logs instead of colored text.</td></tr><tr><td style="text-align:left;"><code>--http3</code></td><td style="text-align:center;"></td><td style="text-align:center;">boolean</td><td style="text-align:center;"><code>false</code></td><td style="text-align:left;">Enables the HTTP/3 QUIC listener on the UDP socket matching <code>--listen</code>.</td></tr></tbody></table><hr><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h2><h3 id="_1-wednesd-init" tabindex="-1">1. <code>wednesd init</code> <a class="header-anchor" href="#_1-wednesd-init" aria-label="Permalink to &quot;1. `wednesd init`&quot;">​</a></h3><p>Initializes a new function project directory with a default template and manifest.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h4 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h4><ul><li><code>&lt;name&gt;</code> <em>(Required)</em>: The name of the function to generate. Must be alphanumeric with dashes or underscores.</li></ul><h4 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webhook-service</span></span></code></pre></div><hr><h3 id="_2-wednesd-dev" tabindex="-1">2. <code>wednesd dev</code> <a class="header-anchor" href="#_2-wednesd-dev" aria-label="Permalink to &quot;2. `wednesd dev`&quot;">​</a></h3><p>Starts a hot-reloading development environment. Watches the project directory for changes to source code or manifests, automatically rebuilding and restarting the runtime daemon.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><h4 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h4><ul><li>Uses filesystem notification events (<code>create</code>, <code>modify</code>, <code>remove</code>).</li><li>Triggers compilation and reloads in-memory instances immediately without manually killing and restarting the process.</li></ul><hr><h3 id="_3-wednesd-deploy" tabindex="-1">3. <code>wednesd deploy</code> <a class="header-anchor" href="#_3-wednesd-deploy" aria-label="Permalink to &quot;3. `wednesd deploy`&quot;">​</a></h3><p>Validates, precompiles, and registers a function manifest into an atomic registry.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MANIFEST_PAT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">H</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">REGISTRY_PAT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">H</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h4 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:center;">Short</th><th style="text-align:center;">Type</th><th style="text-align:center;">Required</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--manifest</code></td><td style="text-align:center;"><code>-m</code></td><td style="text-align:center;">path</td><td style="text-align:center;">Yes</td><td style="text-align:left;">Path to the <code>manifest.toml</code> or <code>wednes.yaml</code> specification.</td></tr><tr><td style="text-align:left;"><code>--registry</code></td><td style="text-align:center;"><code>-r</code></td><td style="text-align:center;">path</td><td style="text-align:center;">Yes</td><td style="text-align:left;">Path to the target <code>registry.json</code> database file.</td></tr></tbody></table><h4 id="process-flow" tabindex="-1">Process Flow <a class="header-anchor" href="#process-flow" aria-label="Permalink to &quot;Process Flow&quot;">​</a></h4><ol><li>Reads and deserializes the manifest.</li><li>Validates <code>name</code>, <code>abi</code> (<code>wednes:function@0.1.0</code>), and runtime constraints.</li><li>Verifies that the <code>.wasm</code> artifact exists and conforms to the WIT world.</li><li>Performs Cranelift precompilation and caching.</li><li>Performs an atomic file swap on <code>&lt;registry&gt;</code> to ensure zero corrupted reads.</li></ol><h4 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to &quot;Example&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./functions/auth/manifest.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/wednes/registry.json</span></span></code></pre></div><hr><h3 id="_4-wednesd-run" tabindex="-1">4. <code>wednesd run</code> <a class="header-anchor" href="#_4-wednesd-run" aria-label="Permalink to &quot;4. `wednesd run`&quot;">​</a></h3><p>Starts the production serverless daemon, reading registered functions and configurations from the registry database.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">REGISTRY_PAT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">H</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [OPTIONS]</span></span></code></pre></div><h4 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:center;">Short</th><th style="text-align:center;">Type</th><th style="text-align:center;">Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--registry</code></td><td style="text-align:center;"><code>-r</code></td><td style="text-align:center;">path</td><td style="text-align:center;">Required</td><td style="text-align:left;">Path to the <code>registry.json</code> database file.</td></tr><tr><td style="text-align:left;"><code>--listen</code></td><td style="text-align:center;"><code>-l</code></td><td style="text-align:center;">string</td><td style="text-align:center;"><code>127.0.0.1:8080</code></td><td style="text-align:left;">Address and port to bind.</td></tr><tr><td style="text-align:left;"><code>--global-concurrency</code></td><td style="text-align:center;"></td><td style="text-align:center;">integer</td><td style="text-align:center;"><code>100</code></td><td style="text-align:left;">Global concurrency permit ceiling.</td></tr><tr><td style="text-align:left;"><code>--memory-budget-mb</code></td><td style="text-align:center;"></td><td style="text-align:center;">integer</td><td style="text-align:center;"><code>1200</code></td><td style="text-align:left;">Daemon memory budget cap.</td></tr><tr><td style="text-align:left;"><code>--default-concurrency</code></td><td style="text-align:center;"></td><td style="text-align:center;">integer</td><td style="text-align:center;"><code>16</code></td><td style="text-align:left;">Fallback concurrency per function.</td></tr><tr><td style="text-align:left;"><code>--http3</code></td><td style="text-align:center;"></td><td style="text-align:center;">boolean</td><td style="text-align:center;"><code>false</code></td><td style="text-align:left;">Enable HTTP/3 QUIC on UDP.</td></tr></tbody></table><h4 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to &quot;Example&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/wednes/registry.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --global-concurrency</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --memory-budget-mb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2048</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --http3</span></span></code></pre></div>',39)])])}const y=e(n,[["render",l]]);export{g as __pageData,y as default};
